class Solution {
    public int smallestEvenMultiple(int n) {
        return n % 2 == 0 ? n : 2 * n;
    }
}

class Solution {
    public int smallestEvenMultiple(int n) {
        return n / gcd(n, 2) * 2;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    }
}

class Solution {
    public int smallestEvenMultiple(int n) {
        if ((n & 1) == 1) {
            return n << 1;
        }
        return n;
    }
}

class Solution {
    public int smallestEvenMultiple(int n) {
        int multiple = n;
        while (multiple % 2 != 0) {
            multiple += n;
        }
        return multiple;
    }
}
